function normalizeTheme(text){return String(text||'').normalize('NFKC').toLowerCase().replace(/[\s　・｜「」『』、。？！?!]/g,'');}
function themeWords(text){const s=normalizeTheme(text);return new Set(Array.from({length:Math.max(0,s.length-1)},(_,i)=>s.slice(i,i+2)));}
function nearTheme(a,b){const na=normalizeTheme(a),nb=normalizeTheme(b);if(!na||!nb)return false;if(na===nb)return true;const wa=themeWords(na),wb=themeWords(nb),same=[...wa].filter(x=>wb.has(x)).length;return same/Math.max(1,Math.min(wa.size,wb.size))>=.72;}
function completeGeneratedCaption(post){if([...String(post.caption||'')].length>=300)return;const products=post.skuIds.length?post.skuIds.map(skuLabel).join('、'):'今回撮影する革や道具';const focus={LEATHER:'表面の模様だけでなく、厚みや柔らかさ、光を受けたときの表情まで見比べると、革ごとの個性が分かりやすくなります。',ANIMAL:'動物の種類だけで決めつけず、部位・なめし・仕上げまで確認することが、革を正しく知る手がかりになります。',AGING:'変化の速さや現れ方は、使う頻度、触れ方、保管環境でも異なります。誰かと同じ色にするのではなく、自分の時間として楽しんでください。',CARE:'まず素材と仕上げを確認し、目立たない場所で少量から試すことが大切です。迷う場合は、自己判断で進めず写真と商品名を添えてご相談ください。',CRAFT:'完成品だけでなく、型紙・裁断・縫製・仕上げのどこで形や使い心地が決まるのかを、手元の動きと一緒にお伝えします。',INDUSTRY:'未確認の情報は断定せず、出典と確認日を確かめたうえで、暮らしや革選びにどう関係するかを整理します。',FASHION:'流行だけを追うのではなく、いつもの服や持ち物に合わせたときの色・大きさ・素材の見え方を考えます。',CUSTOMER:'いただいた質問や使う場面を出発点に、選ぶ前の迷いと使い始めてからの困りごとを一つずつ整理します。'}[post.topicGroup]||'実物を見ながら、暮らしの中で役立つポイントを具体的に確かめます。';post.caption=[post.caption,`今回見るのは「${post.theme}」です。${focus}`,`${products}を例に、見た目だけでは分かりにくい部分も写真や工程で確かめます。使う場面を思い浮かべながら、今持っているものとの違い、手に取るときに確認したい点、長く使うために知っておきたいことを順番にご紹介します。`,`作り手として、形や素材を選んだ理由だけでなく、できることと注意したいことも同じように伝えたいと考えています。気になる点や、ご自身の使い方で迷っていることがあれば、コメントやDMで教えてください。次の投稿やご案内を、実際のお声に沿って分かりやすくする参考にします。`,post.cta].filter(Boolean).join('\n\n');}
createConcept=function(date,index=0,forced,attempt=0){if(forced)return briefConcept(date,index,forced);const c=planContext(date),preferred=chooseAxis(c),axes=[preferred,...Object.keys(AXES).filter(axis=>axis!==preferred)],axis=axes[attempt%axes.length],topic=topicCandidates(axis,c,date,attempt)[attempt%12],template=topicTemplate(topic,axis,index,attempt);BRIEFS.push(template);let post;try{post=briefConcept(date,index,template.id);}finally{BRIEFS.pop();}post.briefId=template.id;post.themeId=template.id;post.primaryAxis=axis;post.parentId=topic.id;post.topicGroup=topic.group;post.derivedTheme=template.title;post.theme=template.title;post.takeaway=template.message;post.researchRequired=!!topic.researchRequired;post.skuIds=conceptSubjects(template,c,attempt);post.subjects=post.skuIds.length?post.skuIds.map(skuLabel).join(' ＋ '):post.subjects;post.cta=safeConceptCta(axis,post.skuIds,index+attempt,date);post.planningReason+=' 正式100テーマから未使用・直近重複・販売状況を確認して選定。';completeGeneratedCaption(post);const invalid=generatedConceptError(post);if(invalid)throw Error('投稿案を追加できません：'+invalid);return post;};
