  originalOpen(title,body+choices,f=>{const snapshot=reviewActualChoice(post,f);const result=onSave(f);if(snapshot){post.actualSnapshot=snapshot;post.actualContentVerified=true;post.revision++;}return result;},onDelete);
  dx('#workForm fieldset.card').insertAdjacentHTML('afterbegin',`<details><summary>予定していた内容を確認</summary><p>${html(post.theme)}｜${html(formats[post.format]||post.format)}</p><p class="exact">${html(post.caption||'本文未設定')}</p><p>${html(post.skuIds.map(skuLabel).join(' ＋ ')||'商品なし')}</p></details>`);
