const originalPayload=analysisPayload;
analysisPayload=function(){const base=originalPayload();const raw=base.posts;return {...base,schema:2,posts:raw.filter(p=>demo.posts.find(x=>x.id===p.id)?.actualSnapshot).map(p=>{const actual=actualPost(demo.posts.find(x=>x.id===p.id));return {...p,...actual,productNames:postLabel(actual),planned:{date:p.date,format:p.format,theme:p.theme},parentTheme:topicLabel(actual)};}),unconfirmedActualPosts:raw.filter(p=>!demo.posts.find(x=>x.id===p.id)?.actualSnapshot).map(p=>({id:p.id,actualAt:p.actualAt,reason:'実際の投稿内容が未確認のため主要分析から除外'})),officialThemes:OFFICIAL_TOPICS,themeGuidance:{ANIMAL:'動物・部位・飼育環境・原皮・なめし・仕上げまで含めて違いを説明し、動物名だけで単純化しない',AGING:'購入した後までつなげる',CARE:'購入後のお客様との接点',CRAFT:'元タンナー・革職人の確認できる経験を活かす',INDUSTRY:'66〜80は投稿制作時に最新の統計・業界情報・公的資料を調査。未確認情報を事実として生成しない',FASHION:'革だけに閉じずファッションや生活とのつながりを楽しむ',CUSTOMER:'関係づくり、購入後のファン化、情報発信・サービス改善・商品開発へつなげる'},additionalThemes:demo.extraThemes,voiceCandidates:voiceCandidates(),periodBalance:axisBalance(raw.map(p=>actualPost(demo.posts.find(x=>x.id===p.id))).filter(Boolean)),monthBalance:axisBalance(demo.posts.filter(p=>p.date.startsWith(demo.planStart.slice(0,7)))),formatCohorts:Object.keys(AXES).flatMap(axis=>[...new Set(demo.posts.map(p=>actualPost(p)?.topicGroup).filter(Boolean))].map(group=>({axis,group,advertising:false,data:formatEvidence(axis,group)}))),brandPrinciples:['CUSTOMER VALUE × INSTAGRAM GROWTH × BUSINESSを同時に見る。売上は価値提供を続けるために必要','固定配分はしない。販売直前は商品・販売、販売後は購入後の利用や楽しみも検討','役立つ話だけにも商品紹介だけにも偏らせない','成功テーマをコピーし続けず、新しい発見・世界観・商品理解・販売・交流・探索を残す','正式100の原文未確認分を生成して埋めない。派生は独立IDで親へ紐づける','INDUSTRY66〜80は要リサーチ。未確認の最新数値・業界・環境情報を事実にしない','実際の投稿と確認日時を使用。未取得を0にしない。7d主要、24h補助','正式商品名は変えずIDで紐づけ。手動編集は選択なしに上書きしない','Storyは知識・参加対話・別商品発見・当日の投稿導線の4枠。返すべき反応を優先。参加型スタンプ1日1回。重複商品はBUSINESS上の理由が必要。絵文字・星占いなし']};};
function extractJsonPayload(raw){const text=String(raw||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{JSON.parse(text);return text;}catch{}for(const start of ['{','[']){const from=text.indexOf(start);if(from<0)continue;for(let to=text.length-1;to>from;to--){if(!'}]'.includes(text[to]))continue;const candidate=text.slice(from,to+1);try{JSON.parse(candidate);return candidate;}catch{}}}throw Error('ChatGPTの返答からJSON部分を読み取れませんでした。JSON部分のみ貼り付けてください。');}
analysisSchema=function(){const p=rangePosts().find(p=>!p.actualAt&&!p.deleted&&p.conceptVersion===2),evidence=demo.reactions[0]?.id||demo.posts[0]?.id;return {schema:2,batchId:'ここを一意の分析IDにする',period:{from:analysisFrom,to:analysisTo},facts:[{text:'実際の記録から確認できた事実',evidence:[evidence]}],trends:[],hypotheses:[{text:'まだ確定していない解釈',evidence:[evidence]}],experiments:[{category:'次回検証',text:'次に何を変え、どの主目的の反応を見るか',evidence:[evidence]}],newThemes:[],proposals:p?[{postId:p.id,expectedRevision:p.revision,evidence:[evidence],changes:Object.fromEntries(['themeId','primaryAxis','parentId','topicGroup','theme','derivedTheme','takeaway','subjects','role','format','caption','hook','cta','sequence','stories','shots','voiceIds','researchRequired'].map(k=>[k,k==='format'?(p.format==='Reel'?'Reel':'Feed'):structuredClone(p[k]??null)]))}]:[]};};
exportPrompt=function(){return `あなたはcian en paclamの編集・運用パートナーです。最上位目的は、お客様に革をもっと楽しんでもらい、困ったときには手助けし、その価値をInstagramでより多くの人へ届けながらブランドも成長することです。
CUSTOMER VALUE / INSTAGRAM GROWTH / BUSINESSを10日と販売周期で同時に考えてください。固定比率なし。売上を弱めず、役立つ投稿だけにも商品紹介だけにも偏らせないこと。
生成順序：期間の役割→主目的→確認済み親テーマ・蓄積テーマ・お客様の声→伝えること→適切な商品/革/工程/道具→形式→構成/本文/Story/撮影を一体化。販売直前は販売商品起点可。
本文はテーマに沿った長文案。未確認の製品性能、体験、統計を作らない。要リサーチは事実化せず確認事項として残す。正式100テーマは原文が確認済みのものだけ使い、追加テーマは新しいIDで区別。
事実・傾向・仮説・次に試すことを分ける。傾向は複数の独立記録IDを根拠にする。同じ投稿の24hと7dだけを複数投稿の傾向にしない。実際の投稿内容が未確認の投稿は主要分析から除外。ただし記録済みの7d/24h数値は参考事実として扱い、予定テーマ・形式・商品・本文の評価根拠に使わない。未取得・0・期間外・広告ありを分け、7dを優先。
各投稿の主目的に合わせて、保存や役立った声、認知やフォロー、商品質問や再販希望を読み取る。再生だけで成功としない。数値から売上・購入を推定しない。形式は同じ目的/テーマ/広告条件で比較し、少数では断定しない。
お客様の声を情報発信または商品開発候補へ紐づける。成功テーマを利用しつつ新しい探索、ブランド、販売を維持。次の企画に具体的に反映する。過去のCarousel実績は履歴として扱い、新しい自動提案の形式はFeed/Reelのみ。
返答は下のschema:2と同じJSONのみ。未知キー不可。newThemesは {id:"extra-一意ID",parentId:"確認済み親IDまたはnull",title:"派生/追加テーマ",group:"分類",evidence:["記録ID"]}。official-IDの新規作成は禁止。
proposalsのテーマを変える場合はprimaryAxis,parentId,topicGroup,theme,derivedTheme,takeaway,subjects,role,format,caption,hook,cta,sequence,stories,shots,voiceIds,researchRequiredを一体で返す。sequenceは{order,visual,words,shotId}。Storyは4枠（1別テーマの知識、2反応への返答を優先、3別商品発見、4今日の投稿への導線）。slot,theme,parentId,topicGroup,materialMode,combinationReason,overlapReason,reactionId,researchRequiredを必要に応じて指定。materialModeは過去素材使用可／新規撮影必要／まとめ撮り対象。shotIdは新規撮影が必要な場合のみ対応する撮影IDを参照。複数商品の変更はchanges.skuIdsとcombinationReasonを指定。商品・カラーは正確なIDで。手動編集済みは差分確認で選ばれたものだけ反映する。
\n返答形式:\n`+JSON.stringify(analysisSchema(),null,2)+'\n\n分析データ:\n'+JSON.stringify(analysisPayload(),null,2);};
validateImport=function(raw){if(raw.length>500000)throw Error('50万文字以内で貼り戻してください');let a;try{a=JSON.parse(raw)}catch{throw Error('JSONのみ貼り戻してください');}const obj=(o,keys)=>{if(!o||typeof o!=='object'||Array.isArray(o)||Object.keys(o).some(k=>!keys.includes(k)))throw Error('未対応の項目があります');},txt=(s,n=18000)=>{if(typeof s!=='string'||!s.trim()||s.length>n)throw Error('文章を確認してください');},arr=(x,n=100)=>{if(!Array.isArray(x)||x.length>n)throw Error('一覧の形式を確認してください');};obj(a,['schema','batchId','period','facts','trends','hypotheses','experiments','newThemes','proposals']);if(a.schema!==2)throw Error('今回のコピーで出力したschema:2を使用してください');txt(a.batchId,100);if(demo.analyses.some(x=>x.batchId===a.batchId))throw Error('この分析は取り込み済みです');obj(a.period,['from','to']);if(a.period.from!==analysisFrom||a.period.to!==analysisTo)throw Error('分析期間が一致しません');const available=new Set([...Object.keys(demo.records),...demo.posts.map(p=>p.id),...demo.reactions.map(r=>r.id),...demo.analyses.map(x=>x.batchId)]);const ev=e=>{arr(e);if(!e.length||e.some(id=>!available.has(id)))throw Error('根拠の記録IDが見つかりません');};for(const key of ['facts','trends','hypotheses','experiments']){arr(a[key],30);a[key].forEach(x=>{obj(x,['text','evidence','category']);txt(x.text,4000);ev(x.evidence);if(x.category&&!['伸ばす','継続','改善','次回検証'].includes(x.category))throw Error('アクション区分を確認してください');if(key==='trends'&&new Set(x.evidence.map(id=>demo.records[id]?.postId||id)).size<2)throw Error('傾向には複数の独立した記録が必要です');});}
 const parent=id=>{if(id!==null&&!OFFICIAL_TOPICS.some(t=>t.id===id&&t.verified))throw Error('確認済みの親テーマだけ使用できます');};arr(a.newThemes,30);const newIds=new Set();a.newThemes.forEach(t=>{obj(t,['id','parentId','title','group','evidence']);txt(t.id,100);if(!t.id.startsWith('extra-')||newIds.has(t.id)||demo.extraThemes.some(x=>x.id===t.id))throw Error('追加テーマIDが不正または重複しています');newIds.add(t.id);parent(t.parentId);txt(t.title,200);txt(t.group,50);ev(t.evidence);});
 arr(a.proposals,30);const ids=new Set(),bundle=['themeId','primaryAxis','parentId','topicGroup','theme','derivedTheme','takeaway','subjects','role','format','caption','hook','cta','sequence','stories','shots','voiceIds','researchRequired'];a.proposals.forEach(x=>{obj(x,['postId','expectedRevision','evidence','changes']);const p=rangePosts().find(p=>p.id===x.postId&&!p.deleted&&!p.actualAt);if(!p||ids.has(x.postId))throw Error('未投稿の対象IDを確認してください');ids.add(x.postId);if(x.expectedRevision!==p.revision)throw Error('コピー後に編集されています。再度コピーしてください');ev(x.evidence);const c=x.changes;obj(c,[...bundle,'skuIds','combinationReason']);if(c.combinationReason)txt(c.combinationReason);if(!Object.keys(c).length)throw Error('変更内容が空です');if(('theme' in c||'derivedTheme' in c||'takeaway' in c)&&bundle.some(k=>!(k in c)))throw Error('テーマ変更は本文・構成・Story・撮影を一体で提案してください');if(c.themeId&&!demo.extraThemes.some(t=>t.id===c.themeId)&&!newIds.has(c.themeId))throw Error('追加・派生テーマIDが見つかりません');if(c.primaryAxis&&!AXES[c.primaryAxis])throw Error('主目的を確認してください');if('parentId' in c)parent(c.parentId);if(c.parentId&&c.topicGroup!==OFFICIAL_TOPICS.find(t=>t.id===c.parentId)?.group)throw Error('親テーマと分類が一致しません');for(const k of ['theme','derivedTheme','takeaway','subjects','role','caption','hook','cta','topicGroup'])if(k in c)txt(c[k]);if(c.theme&&c.derivedTheme!==c.theme)throw Error('派生テーマと投稿テーマを一致させてください');if(c.format&&!['Feed','Reel'].includes(c.format))throw Error('自動形式はFeedまたはReelです');if('researchRequired' in c&&typeof c.researchRequired!=='boolean')throw Error('要リサーチの指定を確認してください');if(c.topicGroup==='INDUSTRY'&&!c.researchRequired)throw Error('INDUSTRYは要リサーチです');if(c.voiceIds){arr(c.voiceIds);if(c.voiceIds.some(id=>!demo.reactions.some(r=>r.id===id)))throw Error('お客様の声IDが不正です');}
 const validSku=list=>{arr(list,8);if(list.some(id=>!sku(id)))throw Error('商品IDが不正です');};if(c.skuIds)validSku(c.skuIds);if(c.shots){arr(c.shots,30);if(!c.shots.length)throw Error('撮影内容が必要です');const seen=new Set();c.shots.forEach(s=>{obj(s,['id','signature','media','what','skuIds','count']);txt(s.id,100);if(seen.has(s.id))throw Error('撮影IDが重複しています');seen.add(s.id);txt(s.signature,1000);txt(s.what,4000);if(!['動画','写真'].includes(s.media)||!Number.isSafeInteger(s.count)||s.count<1||s.count>20)throw Error('撮影項目が不正です');validSku(s.skuIds);});}
 if(c.sequence){arr(c.sequence,30);if(!c.sequence.length)throw Error('構成が必要です');c.sequence.forEach((s,i)=>{obj(s,['order','visual','words','shotId']);if(s.order!==i+1)throw Error('構成の順序を確認してください');txt(s.visual,4000);txt(s.words,4000);if(!(c.shots||p.shots).some(t=>t.id===s.shotId))throw Error('構成と撮影IDがつながっていません');});}
 if(c.stories){arr(c.stories,4);if(c.stories.length!==4)throw Error('Storyは基本4枠です');let polls=0;const counts={};c.stories.forEach(s=>{obj(s,['text','asset','action','purpose','skuIds','participatory','shotId','slot','theme','parentId','topicGroup','materialMode','combinationReason','overlapReason','reactionId','researchRequired','manual','kind','options','correctAnswer','researchBrief','needsAnswer']);for(const k of ['text','asset','action','purpose']){if(k==='text'&&s.researchRequired&&s[k]==='')continue;txt(s[k],4000);}if(/\p{Extended_Pictographic}/u.test(s.text)||/星占い|星座占い/.test(s.text))throw Error('Storyに絵文字・星占いは使いません');validSku(s.skuIds);if(typeof s.participatory!=='boolean')throw Error('参加型の指定が必要です');if(s.participatory)polls++;if(s.parentId)parent(s.parentId);if((s.topicGroup==='INDUSTRY'||s.topicGroup==='FASHION')&&!s.researchRequired)throw Error('業界・ニュース・トレンドは要リサーチとして扱ってください');for(const id of s.skuIds)if((c.skuIds||p.skuIds).includes(id)&&!s.overlapReason)counts[id]=(counts[id]||0)+1;if(s.shotId&&!(c.shots||p.shots).some(t=>t.id===s.shotId))throw Error('Storyの撮影IDが見つかりません');});if(polls>1||Object.values(counts).some(n=>n>1)||!c.stories.some(s=>!s.skuIds.length))throw Error('Storyの重複商品・参加回数・見る理由を確認してください');}
 });return a;};
const originalApply=applyImport;applyImport=function(){if(!pendingImport)return;const topics=structuredClone(pendingImport.newThemes||[]),batch=pendingImport.batchId;originalApply();if(demo.analyses.some(a=>a.batchId===batch)){topics.forEach(t=>demo.extraThemes.push({...t,status:t.parentId?'派生テーマ':'追加テーマ',source:batch,uses:[]}));persist();refreshWork();}};
const originalAnalysisRender=renderAnalysis;renderAnalysis=function(){originalAnalysisRender();dx('#analysisCounts').textContent=analysisPayload().posts.length+'投稿（実内容確認済み） / 実内容未確認 '+analysisPayload().unconfirmedActualPosts.length+'件 / 質問・反応 '+demo.reactions.length+'件';dx('#analysisHistoryWork').innerHTML=demo.analyses.slice().reverse().map(a=>`<details><summary>${a.period.from}〜${a.period.to} · ${a.appliedPostIds.length}投稿へ反映</summary>${[['facts','事実'],['trends','傾向'],['hypotheses','仮説'],['experiments','次に試すこと']].map(([k,n])=>`<h4>${n}</h4>${(a[k]||[]).map(x=>`<p>${html(x.text)}<br><small>根拠：${html(x.evidence.join(', '))}</small></p>`).join('')}`).join('')}</details>`).join('');};
periodSummary=function(from,to){const ps=demo.posts.filter(p=>p.actualAt&&jstDate(p.actualAt)>=from&&jstDate(p.actualAt)<=to);return ['Reel','Carousel','Feed'].map(format=>{const posts=ps.filter(p=>(actualPost(p)?.format||p.format)===format),ready=posts.map(primaryRecord).filter(Boolean),sum=k=>ready.reduce((n,r)=>n+(r[k]||0),0),views=sum('views');return {format:formats[format],posts:posts.length,complete:ready.length,pending:posts.length-ready.length,views,likes:sum('likes'),comments:sum('comments'),saves:sum('saves'),savePerView:views?sum('saves')/views:null,adPosts:posts.filter(p=>demo.ads.some(a=>a.postId===p.id)).length};});};
// 既存イベントを使う画面は維持。実投稿登録のみ、新しい実績フォームへ送る。
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.workPublish){e.stopImmediatePropagation();editActual(b.dataset.workPublish);}if(b.dataset.actualEdit){e.stopImmediatePropagation();editActual(b.dataset.actualEdit);}if(b.dataset.conceptEdit)editConcept(b.dataset.conceptEdit);},true);
const axisMetaEdit=editPostMeta;editPostMeta=function(id){axisMetaEdit(id);const form=dx('#workForm'),save=form.onsubmit;form.onsubmit=e=>{save(e);if(!dx('#workDialog').open){const p=demo.posts.find(p=>p.id===id);p.derivedTheme=p.theme;p.reviewNeeded=['本文・Story・構成とテーマのつながりを確認'];persist();refreshWork();}};};
const confirmedAnalysisPayload=analysisPayload;
analysisPayload=function(){
 const data=confirmedAnalysisPayload();
 const actualIds=new Set([...data.posts,...data.unconfirmedActualPosts].map(p=>p.id));
 const previousAnalyses=(data.previousAnalyses||[]).filter(a=>a.period?.from<=data.period.to&&a.period?.to>=data.period.from||[...(a.facts||[]),...(a.trends||[]),...(a.hypotheses||[]),...(a.experiments||[])].some(x=>(x.evidence||[]).some(id=>actualIds.has(id)||actualIds.has(String(id).split('|')[0]))));
 return {...data,previousAnalyses,unconfirmedActualPosts:data.unconfirmedActualPosts.map(entry=>{
  const referenceRecords=allTasks().filter(t=>t.p.id===entry.id).flatMap(t=>{const r=demo.records[t.key];if(!r)return [];const values=Object.fromEntries(Object.keys(RESULT_METRICS).map(k=>[k,r[k]??null]));return [{key:t.key,postId:entry.id,stage:t.stage,observedAt:r.observedAt||null,captureBand:captureBand(t,r),recordState:recordState(t),values}];});
  return {...entry,referenceRecords,advertised:!!demo.ads?.some(a=>a.postId===entry.id),reason:'実投稿内容未確認。数値は参考記録とし、予定のテーマ・商品・本文へ紐づけて評価しない'};
 })};
};
