document.head.insertAdjacentHTML('beforeend','<style>.takeaway{border-left:3px solid #495c58;padding:10px 12px;background:#f0f2ef}.stories-always{margin:20px 0}.stories-always .story-card{margin:10px 0;padding:14px;border:1px solid #d8d8d3;border-radius:12px}.axis-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.axis-counts>div{padding:10px 6px;background:#f0f2ef;border-radius:10px;text-align:center}.axis-counts strong{font-size:22px;display:block}.axis-counts small{display:block;font-size:12px}.concept-detail{margin:12px 0}#planAxisSummary p{line-height:1.65}.wlabel textarea{width:100%;box-sizing:border-box}</style>');
