const basePreviewImport=previewImport;previewImport=function(){basePreviewImport();if(pendingImport)dx('#importPreview').insertAdjacentHTML('afterbegin',`<details open><summary>分析と追加テーマを確認</summary>${[['facts','事実'],['trends','傾向'],['hypotheses','仮説'],['experiments','次に試すこと']].map(([k,label])=>`<h4>${label}</h4>${pendingImport[k].map(x=>`<p>${html(x.text)}<br><small>根拠：${html(x.evidence.join(', '))}</small></p>`).join('')||'<p>記録なし</p>'}`).join('')}${pendingImport.newThemes.length?'<h4>正式100とは別に保存するテーマ</h4>'+pendingImport.newThemes.map(t=>`<p>${html(t.title)}<br><small>${html(t.parentId||'親テーマ未指定')}</small></p>`).join(''):''}</details>`);};
const importedApply=applyImport;applyImport=function(){const batch=pendingImport?.batchId;importedApply();const a=demo.analyses.find(a=>a.batchId===batch);if(a){for(const id of a.appliedPostIds){const p=demo.posts.find(p=>p.id===id);for(const rid of p.voiceIds||[]){const r=demo.reactions.find(r=>r.id===rid);if(r&&!r.uses.some(u=>u.postId===id&&u.analysisId===batch))r.uses.push({date:p.date,note:p.theme,postId:id,analysisId:batch});}const topic=demo.extraThemes.find(t=>t.id===p.themeId);if(topic&&!topic.uses.some(u=>u.postId===id))topic.uses.push({postId:id,date:p.date});}persist();refreshWork();}};
